--
-- Doublure de structure pour la vue `vue_abones_facturation`
--
CREATE TABLE IF NOT EXISTS `vue_abones_facturation` (
    `id` int(6) unsigned,
    `id_compteur` int(5) unsigned,
    `id_aep` int(4) unsigned,
    `id_mois` int(3) unsigned,
    `id_abone` int(4) unsigned,
    `nom_abone` varchar(128),
    `id_reseau` int(3) unsigned,
    `numero_telephone` varchar(16),
    `mois` varchar(32),
    `id_constante_reseau` int(2) unsigned,
    `id_mois_facturation` int(3) unsigned,
    `date_facturation` date,
    `date_depot` date,
    `ancien_index` decimal(8, 2),
    `nouvel_index` decimal(7, 2) unsigned,
    `id_facture` int(4) unsigned,
    `date_releve` date,
    `penalite` decimal(15, 2),
    `numero_compte_anticipation` varchar(16),
    `prix_entretient_compteur` int(5) unsigned,
    `prix_metre_cube_eau` int(5) unsigned,
    `prix_tva` decimal(7, 2) unsigned,
    `consommation` decimal(9, 2),
    `montant_conso` decimal(20, 2),
    `montant_conso_entretien` decimal(21, 2),
    `montant_conso_tva` decimal(33, 8),
    `montant_total` decimal(34, 8),
    `montant_restant` decimal(35, 8),
    `montant_verse` decimal(15, 2),
    `montant_a_valider` decimal(34, 8),
    `impaye` decimal(35, 8)
);
