--
-- Doublure de structure pour la vue `v_intervention_couts`
--
CREATE TABLE IF NOT EXISTS `v_intervention_couts` (
    `intervention_id` int(11),
    `titre` varchar(200),
    `aep_id` int(11),
    `cout_prevu_affectations` decimal(37, 2),
    `cout_reel_affectations` decimal(37, 2)
);
-- --------------------------------------------------------

--
-- Structure de la vue `vue_abones_facturation`
--
DROP TABLE IF EXISTS `vue_abones_facturation`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`localhost` SQL SECURITY DEFINER VIEW `vue_abones_facturation` AS
select
    `i`.`id` AS `id`,
    `i`.`id_compteur` AS `id_compteur`,
    `cr`.`id_aep` AS `id_aep`,
    `mf`.`id` AS `id_mois`,
    `a`.`id` AS `id_abone`,
    `a`.`nom` AS `nom_abone`,
    `a`.`id_reseau` AS `id_reseau`,
    `a`.`numero_telephone` AS `numero_telephone`,
    `mf`.`mois` AS `mois`,
    `cr`.`id` AS `id_constante_reseau`,
    `i`.`id_mois_facturation` AS `id_mois_facturation`,
    `mf`.`date_facturation` AS `date_facturation`,
    `mf`.`date_depot` AS `date_depot`,
    `i`.`ancien_index` AS `ancien_index`,
    `i`.`nouvel_index` AS `nouvel_index`,
    `f`.`id` AS `id_facture`,
    `mf`.`date_releve` AS `date_releve`,
    `f`.`penalite` AS `penalite`,
    `a`.`numero_compte_anticipation` AS `numero_compte_anticipation`,
    `cr`.`prix_entretient_compteur` AS `prix_entretient_compteur`,
    `cr`.`prix_metre_cube_eau` AS `prix_metre_cube_eau`,
    `cr`.`prix_tva` AS `prix_tva`,
    (
        `i`.`nouvel_index` - `i`.`ancien_index`
    ) AS `consommation`,
    (
        (
            `i`.`nouvel_index` - `i`.`ancien_index`
        ) * `cr`.`prix_metre_cube_eau`
    ) AS `montant_conso`,
    (
        (
            (
                `i`.`nouvel_index` - `i`.`ancien_index`
            ) * `cr`.`prix_metre_cube_eau`
        ) + `cr`.`prix_entretient_compteur`
    ) AS `montant_conso_entretien`,
    (
        (
            (
                (
                    `i`.`nouvel_index` - `i`.`ancien_index`
                ) * `cr`.`prix_metre_cube_eau`
            ) + `cr`.`prix_entretient_compteur`
        ) * (1 + (`cr`.`prix_tva` / 100))
    ) AS `montant_conso_tva`,
    (
        (
            (
                (
                    (
                        `i`.`nouvel_index` - `i`.`ancien_index`
                    ) * `cr`.`prix_metre_cube_eau`
                ) + `cr`.`prix_entretient_compteur`
            ) * (1 + (`cr`.`prix_tva` / 100))
        ) + `f`.`penalite`
    ) AS `montant_total`,
    (
        (
            (
                (
                    (
                        (
                            `i`.`nouvel_index` - `i`.`ancien_index`
                        ) * `cr`.`prix_metre_cube_eau`
                    ) + `cr`.`prix_entretient_compteur`
                ) * (1 + (`cr`.`prix_tva` / 100))
            ) + `f`.`penalite`
        ) - `f`.`montant_verse`
    ) AS `montant_restant`,
    `f`.`montant_verse` AS `montant_verse`,
    least(
        (
            (
                (
                    (
                        (
                            `i`.`nouvel_index` - `i`.`ancien_index`
                        ) * `cr`.`prix_metre_cube_eau`
                    ) + `cr`.`prix_entretient_compteur`
                ) * (1 + (`cr`.`prix_tva` / 100))
            ) + `f`.`penalite`
        ),
        `f`.`montant_verse`
    ) AS `montant_a_valider`,
    (
        (
            (
                (
                    (
                        (
                            `i`.`nouvel_index` - `i`.`ancien_index`
                        ) * `cr`.`prix_metre_cube_eau`
                    ) + `cr`.`prix_entretient_compteur`
                ) * (1 + (`cr`.`prix_tva` / 100))
            ) + `f`.`penalite`
        ) - `f`.`montant_verse`
    ) AS `impaye`
from (
        (
            (
                (
                    `abone` `a`
                    join `facture` `f` on ((`a`.`id` = `f`.`id_abone`))
                )
                join `indexes` `i` on ((`f`.`id_indexes` = `i`.`id`))
            )
            join `mois_facturation` `mf` on (
                (
                    `i`.`id_mois_facturation` = `mf`.`id`
                )
            )
        )
        join `constante_reseau` `cr` on (
            (
                `mf`.`id_constante` = `cr`.`id`
            )
        )
    );

-- --------------------------------------------------------

--
-- Structure de la vue `v_intervention_couts`
--
DROP TABLE IF EXISTS `v_intervention_couts`;

CREATE ALGORITHM = UNDEFINED DEFINER = `root` @`localhost` SQL SECURITY DEFINER VIEW `v_intervention_couts` AS
select
    `i`.`id` AS `intervention_id`,
    `i`.`titre` AS `titre`,
    `i`.`aep_id` AS `aep_id`,
    (
        ifnull(sum(`irh`.`cout_prevu`), 0) + ifnull(sum(`irm`.`cout_prevu`), 0)
    ) AS `cout_prevu_affectations`,
    (
        ifnull(sum(`irh`.`cout_reel`), 0) + ifnull(sum(`irm`.`cout_reel`), 0)
    ) AS `cout_reel_affectations`
from (
        (
            `interventions` `i`
            left join `intervention_rh` `irh` on (
                (
                    `irh`.`intervention_id` = `i`.`id`
                )
            )
        )
        left join `intervention_rm` `irm` on (
            (
                `irm`.`intervention_id` = `i`.`id`
            )
        )
    )
group by
    `i`.`id`,
    `i`.`titre`,
    `i`.`aep_id`;

